export const LanguageProvider = ({ children }) => {
  // ✅ Default English
  const [language, setLanguageState] = useState('en');
  
  // ✅ Auth store se user aur branch uthayein
  const { user, selectedBranch } = useAuthStore();

  // ✅ Jab bhi user ya branch change ho, backend se store ki language fetch karein
  useEffect(() => {
    const fetchStoreLanguage = async () => {
      try {
        const isAdminLevel = user?.role === 'super_admin' || user?.role === 'store_admin';
        const branchId = selectedBranch || user?.branchId?._id || user?.branchId;

        if (isAdminLevel && branchId) {
          console.log('Fetching language for branch:', branchId);
          const { data } = await api.get(`/settings?branchId=${branchId}`);
          console.log('Fetched language from backend:', data?.language);
          if (data && data.language) {
            setLanguageState(data.language);
          }
        } else if (!user) {
          // Agar user login nahi hai (Landing/Login page), to localStorage ya default use karein
          const saved = localStorage.getItem('appLanguage') || 'en';
          setLanguageState(saved);
        }
      } catch (error) {
        console.error("Failed to load store language", error);
      }
    };

    fetchStoreLanguage();
  }, [user, selectedBranch]);

  // ✅ Language change karne ka function (Backend mein save karega)
  const setLanguage = async (langCode) => {
    setLanguageState(langCode); // UI foran update karein
    
    const isAdminLevel = user?.role === 'super_admin' || user?.role === 'store_admin';
    const branchId = selectedBranch || user?.branchId?._id || user?.branchId;

    console.log('=== LANGUAGE CHANGE ===');
    console.log('langCode:', langCode);
    console.log('isAdminLevel:', isAdminLevel);
    console.log('branchId:', branchId);

    // Agar user login hai, to backend (Store Settings) mein save karein
    if (isAdminLevel && branchId) {
      try {
        const res = await api.put('/settings', { 
          branchId: branchId, 
          language: langCode 
        });
        console.log('✅ Language saved to backend:', res.data);
      } catch (error) {
        console.error("❌ Failed to save language:", error.response?.data || error.message);
      }
    } else {
      // Agar landing page par hai, to localStorage use karein
      localStorage.setItem('appLanguage', langCode);
      console.log('Saved to localStorage (no user/branch)');
    }
  };

  const t = (key) => translations[language]?.[key] || translations['en'][key] || key;

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => useContext(LanguageContext);